import {test,expect} from 'bun:test'
import {readFile} from 'node:fs/promises'
import {m78ContinuationSourcePins,M78_CONTINUATION_EVIDENCE_PINS} from '../../tools/staging/m78-continuation-source-pins'
const sha=(s:string|Uint8Array)=>new Bun.CryptoHasher('sha256').update(s).digest('hex')
test('frozen root wrapper gates precede credential unseal and forwards actual restart pin',async()=>{
 const s=await readFile('.superpowers/m78-private-continuation-journey.ps1','utf8');expect(sha(s)).toBe('b2fbeceb45ed127b1540ed95ff7c06ef729761e5a68fb4ec8ad9391b4b42a9c2');const unseal=s.indexOf('[Security.Cryptography.ProtectedData]::Unprotect');expect(unseal).toBeGreaterThan(0);
 for(const guard of ['wrong admission','wrong recipe','wrong evidence','wrong runtime','stale runtime','duplicate source','missing source','reviewed closure mismatch','complete source closure changed','source gate mismatch','prior closure changed','missing original outcome evidence','actual restart required'])expect(s.indexOf(guard)).toBeGreaterThan(0),expect(s.indexOf(guard)).toBeLessThan(unseal);
 expect(s).toContain("$age.TotalSeconds -lt 0 -or $age.TotalMinutes -gt 15");expect(s).toContain('-NotePropertyName restartAttestation -NotePropertyValue $admission.artifacts.restart');expect(s).toContain("'tools/staging/check-m78-continuation.ts'");expect(s).toContain('$start.RedirectStandardInput=$true');expect(s).toContain('$start.CreateNoWindow=$true');
})
test('reviewed 143-file closure and original outcome pins equal actual bytes',async()=>{
 const raw=await readFile('evaluations/research-qa/m78-continuation-journey-preparation.json');expect(sha(raw)).toBe('e1c7f6dfa24aec324022809515ccb9181ccc9ea66f731601ab17528f2903ae4f');const review=JSON.parse(raw.toString());const current=await m78ContinuationSourcePins();expect(current).toHaveLength(143);expect(current).toEqual(review.sourcePins);expect(review.evidencePins).toEqual([...M78_CONTINUATION_EVIDENCE_PINS]);for(const pin of [...current,...review.evidencePins])expect(sha(await readFile(pin.path))).toBe(pin.sha256);
})
test('CI invokes both native challenge files with the exact supported baseline',async()=>{const s=await readFile('.github/workflows/verify.yml','utf8');expect(s).toContain('run: bun test evaluations/research-qa/m78-perf-concurrency.test.ts evaluations/research-qa/m78-perf-independent.test.ts');expect(s).toContain('M78_PERF_NATIVE_BASELINE_URL: postgres://m63_test_admin@127.0.0.1:55463/m63_integration')})

param(
  [Parameter(Mandatory=$true)][ValidateSet('baseline','exercise','revisit')][string]$Mode,
  [Parameter(Mandatory=$true)][ValidatePattern('^[a-f0-9]{64}$')][string]$GateSha256
)
$ErrorActionPreference='Stop'
try {
  $workspace=[IO.Path]::GetFullPath('C:/Users/nimab/.codex/worktrees/4441/Neuvetra')
  function Read-PinnedFile($pin) {
    if($pin.sha256 -cnotmatch '^[a-f0-9]{64}$'){throw 'invalid pin'}
    $resolved=[IO.Path]::GetFullPath((Join-Path $workspace $pin.path))
    if(-not $resolved.StartsWith($workspace+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'outside workspace'}
    if((Get-FileHash -LiteralPath $resolved -Algorithm SHA256).Hash.ToLowerInvariant() -cne $pin.sha256){throw 'changed artifact'}
    return [IO.File]::ReadAllText($resolved)
  }
  $admission=Read-PinnedFile @{path='.superpowers/m78-continuation-journey-gate.json';sha256=$GateSha256} | ConvertFrom-Json
  if($admission.profile -cne 'm78-root-continuation-journey-gate-v1' -or $admission.mode -cne $Mode){throw 'wrong admission'}
  $gate=$admission.gate
  if($gate.status -cne 'm78_continuation_candidate_reviewed' -or $gate.expectedApplicationPosts -ne 37){throw 'wrong recipe'}
  if($admission.artifacts.independentReview.sha256 -cne $gate.independentReviewSha256 -or $admission.artifacts.operatorRecoveryReceipt.sha256 -cne $gate.operatorRecoveryReceiptSha256){throw 'wrong evidence'}
  foreach($artifact in $admission.artifacts.PSObject.Properties){$null=Read-PinnedFile $artifact.Value}
  $runtime=Read-PinnedFile $admission.artifacts.runtime | ConvertFrom-Json
  if($runtime.status -cne 'm78_runtime_verified' -or $runtime.commit -cne $gate.reviewedApplicationCommit -or $runtime.schemaVersion -ne 21){throw 'wrong runtime'}
  $observed=[DateTimeOffset]::Parse($runtime.observedAt)
  $age=[DateTimeOffset]::UtcNow-$observed
  if($age.TotalSeconds -lt 0 -or $age.TotalMinutes -gt 15){throw 'stale runtime'}
  $required=@('tools/staging/check-m78-continuation.ts','tools/staging/m78-continuation-plan.ts','packages/neuvetra-database/src/migrations/0021_scope1_inventory.sql','bun.lock','tools/staging/m78-continuation-source-pins.ts')
  $seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
  foreach($pin in $admission.sourcePins){if(-not $seen.Add($pin.path)){throw 'duplicate source'};$null=Read-PinnedFile $pin}
  foreach($entry in $required){if(-not $seen.Contains($entry)){throw 'missing source'}}
  $review=Read-PinnedFile $admission.artifacts.independentReview | ConvertFrom-Json
  if($review.status -cne 'm78_independent_continuation_preparation_passed' -or $review.reviewerId -ceq '/root' -or -not $review.reviewerId){throw 'missing independent review'}
  $pinText=$admission.sourcePins | ConvertTo-Json -Depth 6 -Compress
  if(($review.sourcePins | ConvertTo-Json -Depth 6 -Compress) -cne $pinText){throw 'reviewed closure mismatch'}
  $pinCheck=[Diagnostics.ProcessStartInfo]::new()
  $pinCheck.FileName='C:/Users/nimab/.bun/bin/bun.exe';$pinCheck.WorkingDirectory=$workspace
  $pinCheck.ArgumentList.Add('run');$pinCheck.ArgumentList.Add((Join-Path $workspace 'tools/staging/m78-continuation-source-pins.ts'))
  $pinCheck.UseShellExecute=$false;$pinCheck.CreateNoWindow=$true;$pinCheck.RedirectStandardOutput=$true;$pinCheck.RedirectStandardError=$true
  $pinProcess=[Diagnostics.Process]::Start($pinCheck)
  $pinOutput=$pinProcess.StandardOutput.ReadToEndAsync();$pinErrors=$pinProcess.StandardError.ReadToEndAsync();$pinProcess.WaitForExit()
  if($pinProcess.ExitCode -ne 0 -or (($pinOutput.Result | ConvertFrom-Json | ConvertTo-Json -Depth 6 -Compress) -cne $pinText)){throw 'complete source closure changed'}
  foreach($binding in @(@{path=$required[0];hash=$gate.harnessSha256},@{path=$required[1];hash=$gate.recipeSha256},@{path=$required[2];hash=$gate.migrationSha256})){
    if(($admission.sourcePins | Where-Object path -CEQ $binding.path).sha256 -cne $binding.hash){throw 'source gate mismatch'}
  }
  $m77=@{path='.superpowers/m77-hosted-continuation.jsonl';sha256='223a91a711026bf4be6c299ed9b83876a9bdc72440889fc607969dcbb338bc0c'}
  $prior=Read-PinnedFile $m77
  if((($prior.TrimEnd() -split "`n")[-1] | ConvertFrom-Json).sha256 -cne '19343893f2efa0b35c787c6516b6110c951378470fb8d547087bd7931778709e'){throw 'prior closure changed'}
  foreach($evidencePin in $review.evidencePins){$null=Read-PinnedFile $evidencePin}
  if($review.evidencePins.Count -ne 3){throw 'missing original outcome evidence'}
  if($Mode -ceq 'revisit'){
    $restart=Read-PinnedFile $admission.artifacts.restart | ConvertFrom-Json
    if($restart.phase -cne 'restart' -or $restart.status -cne 'm78_runtime_verified' -or $restart.commit -cne $gate.reviewedApplicationCommit -or $restart.restartAcknowledged -ne $true){throw 'actual restart required'}
  }
  Add-Type -AssemblyName System.Security
  $raw=[Security.Cryptography.ProtectedData]::Unprotect([IO.File]::ReadAllBytes('C:/Users/nimab/Neuvetra/m63-runtime/recovery/m63-private-config.json.dpapi'),$null,[Security.Cryptography.DataProtectionScope]::CurrentUser)
  $data=[Text.Encoding]::UTF8.GetString($raw) | ConvertFrom-Json
  $data | Add-Member -NotePropertyName mode -NotePropertyValue $Mode -Force
  $data | Add-Member -NotePropertyName gate -NotePropertyValue $gate -Force
  $data | Add-Member -NotePropertyName acceptedM77 -NotePropertyValue @{journalSha256=$m77.sha256;headSha256='19343893f2efa0b35c787c6516b6110c951378470fb8d547087bd7931778709e'} -Force
  if($Mode -ceq 'revisit'){$data | Add-Member -NotePropertyName restartAttestation -NotePropertyValue $admission.artifacts.restart -Force}
  $payload=$data | ConvertTo-Json -Depth 20 -Compress
  $start=[Diagnostics.ProcessStartInfo]::new()
  $start.FileName='C:/Users/nimab/.bun/bin/bun.exe';$start.WorkingDirectory=$workspace
  $start.ArgumentList.Add('run');$start.ArgumentList.Add((Join-Path $workspace 'tools/staging/check-m78-continuation.ts'))
  $start.UseShellExecute=$false;$start.CreateNoWindow=$true
  $start.RedirectStandardInput=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true
  $process=[Diagnostics.Process]::Start($start)
  $process.StandardInput.Write($payload);$process.StandardInput.Close()
  $output=$process.StandardOutput.ReadToEndAsync();$errors=$process.StandardError.ReadToEndAsync()
  $process.WaitForExit();Write-Output $output.Result
  if($process.ExitCode -ne 0){Write-Output 'M78 journey failed; sensitive diagnostics withheld.';exit 1}
}catch{Write-Output 'M78 journey unavailable; sensitive diagnostics withheld.';exit 1}
